// src/tools/transferNativeToken.ts
function registerTransferNativeToken(server) {
  server.tool("Send_BNB", "\uD83D\uDC8ETransfer native token (BNB), Before execution, check the wallet information first", {
    recipientAddress: exports_external.string(),
    amount: exports_external.string()
  }, async ({ recipientAddress, amount }) => {
    let txHash = undefined;
    try {
      const account = await getAccount();
      txHash = await walletClient(account).sendTransaction({
        to: recipientAddress,
        value: parseEther(amount)
      });
      const txUrl = await checkTransactionHash(txHash);
      return {
        content: [
          {
            type: "text",
            text: `Transaction sent successfully. ${txUrl}`,
            url: txUrl
          }
        ]
      };
    } catch (error46) {
      const errorMessage = error46 instanceof Error ? error46.message : String(error46);
      const txUrl = buildTxUrl(txHash);
      return {
        content: [
          {
            type: "text",
            text: `transaction failed: ${errorMessage}`,
            url: txUrl
          }
        ],
        isError: true
      };
    }
  });
}

