// src/tools/transferBEP20Token.ts
function registerTransferBEP20Token(server) {
  server.tool("Send_BEP20_Token", "\uD83D\uDCE4Send any BEP-20 token to another wallet (requires wallet check first)", {
    recipientAddress: exports_external.string(),
    amount: exports_external.string(),
    address: exports_external.string()
  }, async ({ recipientAddress, amount, address }) => {
    let txHash = undefined;
    try {
      const account = await getAccount();
      const client = walletClient(account).extend(publicActions);
      const contract = getContract({
        address,
        abi: bep20abi,
        client
      });
      const decimals = await contract.read.decimals();
      const parsedAmount = parseUnits(amount, decimals);
      txHash = await contract.write.transfer([
        `0x${recipientAddress.replace("0x", "")}`,
        parsedAmount
      ], {
        gas: BigInt(1e5)
      });
      const txUrl = await checkTransactionHash(txHash);
      return {
        content: [
          {
            type: "text",
            text: `BEP-20 token transfer sent successfully. ${txUrl}`,
            url: txUrl
          }
        ]
      };
    } catch (error46) {
      const errorMessage = error46 instanceof Error ? error46.message : String(error46);
      const txUrl = buildTxUrl(txHash);
      return {
        content: [
          {
            type: "text",
            text: `transaction failed: ${errorMessage}`,
            url: txUrl
          }
        ],
        isError: true
      };
    }
  });
}

