// src/functions/pancakeSwapTool.ts
var getToken2 = async (token) => {
  if (token.toUpperCase() === "BNB") {
    return Native.onChain(ChainId.BSC);
  }
  let address = token.toLowerCase();
  let decimal;
  const url2 = "https://tokens.pancakeswap.finance/pancakeswap-extended.json";
  const resp = await fetch(url2);
  const data = await resp.json();
  let tokens = data.tokens;
  let symbol2;
  if (!isAddress(address)) {
    const tokenInfo = tokens.find((item) => item.symbol.toLowerCase() === address);
    if (!tokenInfo) {
      throw new Error("Token not found");
    }
    address = tokenInfo.address;
    decimal = tokenInfo.decimals;
    symbol2 = tokenInfo.symbol;
  } else {
    const tokenInfo = tokens.find((item) => item.address.toLowerCase() === address);
    if (!tokenInfo) {
      const contract = getContract({
        address,
        abi: bep20abi,
        client: publicClient
      });
      decimal = await contract.read.decimals();
      symbol2 = await contract.read.symbol();
    } else {
      decimal = tokenInfo.decimals;
      symbol2 = tokenInfo.symbol;
    }
  }
  return new Token(ChainId.BSC, address, decimal, symbol2);
};
var pancakeSwap = async ({
  account,
  inputToken,
  outputToken,
  amount
}) => {
  const chainId = ChainId.BSC;
  let currencyA = await getToken2(inputToken);
  let currencyB = await getToken2(outputToken);
  let amountDecimal = currencyA.decimals;
  const parseAmountIn = parseUnits(amount, amountDecimal);
  const amountValue = CurrencyAmount.fromRawAmount(currencyA, parseAmountIn);
  if (!currencyA.isNative) {
    const TokenContract = getContract({
      address: currencyA.address,
      abi: erc20Abi,
      client: {
        wallet: walletClient(account),
        public: publicClient
      }
    });
    if (!TokenContract.write || !TokenContract.write.approve || !TokenContract.read.allowance) {
      throw new Error("Unable to Swap Tokens");
    }
    amountDecimal = await TokenContract.read.decimals();
    const smartRouterAddress = SMART_ROUTER_ADDRESSES[ChainId.BSC];
    const allowance = await TokenContract.read.allowance([account.address, smartRouterAddress]);
    if (allowance < parseAmountIn) {
      const approveResult = await TokenContract.write.approve([smartRouterAddress, parseAmountIn]);
      await publicClient.waitForTransactionReceipt({
        hash: approveResult
      });
    }
  }
  const quoteProvider = smartRouter_exports.createQuoteProvider({
    onChainProvider: () => publicClient
  });
  const v3SubgraphClient = new GraphQLClient("https://api.thegraph.com/subgraphs/name/pancakeswap/exchange-v3-bsc1");
  const v2SubgraphClient = new GraphQLClient("https://proxy-worker-api.pancakeswap.com/bsc-exchange1");
  const [v2Pools, v3Pools] = await Promise.all([
    smartRouter_exports.getV3CandidatePools({
      onChainProvider: () => publicClient,
      subgraphProvider: () => v3SubgraphClient,
      currencyA,
      currencyB,
      subgraphFallback: false
    }),
    smartRouter_exports.getV2CandidatePools({
      onChainProvider: () => publicClient,
      v2SubgraphProvider: () => v2SubgraphClient,
      v3SubgraphProvider: () => v3SubgraphClient,
      currencyA,
      currencyB
    })
  ]);
  const pools5 = [...v2Pools, ...v3Pools];
  const trade = await smartRouter_exports.getBestTrade(amountValue, currencyB, TradeType.EXACT_INPUT, {
    gasPriceWei: () => publicClient.getGasPrice(),
    maxHops: 2,
    maxSplits: 2,
    poolProvider: smartRouter_exports.createStaticPoolProvider(pools5),
    quoteProvider,
    quoterOptimization: true
  });
  const { value, calldata } = SwapRouter3.swapCallParameters(trade, {
    recipient: account.address,
    slippageTolerance: new Percent(500, 1e4)
  });
  const tx = {
    account: account.address,
    to: SMART_ROUTER_ADDRESSES[chainId],
    data: calldata,
    value: hexToBigInt(value)
  };
  const gasEstimate = await publicClient.estimateGas(tx);
  const calculateGasMargin = (value2, margin = 1000n) => {
    return value2 * (10000n + margin) / 10000n;
  };
  const txHash = await walletClient(account).sendTransaction({
    account,
    chainId,
    to: SMART_ROUTER_ADDRESSES[chainId],
    data: calldata,
    value: hexToBigInt(value),
    gas: calculateGasMargin(gasEstimate)
  });
  return txHash;
};

