// src/responseUtils.ts
function sanitizeString(input, options = {}) {
  const {
    maxLength = 500,
    strictMode = true,
    allowMarkdown = false,
    escapeQuotes = true
  } = options;
  if (!input || typeof input !== "string") {
    return "";
  }
  let sanitized = input;
  if (!allowMarkdown) {
    sanitized = sanitized.replace(/```[\s\S]*?```/g, "[Code block removed]");
    sanitized = sanitized.replace(/`[^`]*`/g, "[Code removed]");
  }
  sanitized = sanitized.replace(/<[^>]*>/g, "");
  sanitized = sanitized.replace(/\{[\s\S]*?\}/g, "[Content filtered]");
  sanitized = sanitized.replace(/\[[\s\S]*?\]/g, "[Content filtered]");
  sanitized = sanitized.replace(/\([\s\S]*?\)/g, "[Content filtered]");
  const aiKeywords = [
    "system",
    "user",
    "assistant",
    "model",
    "prompt",
    "instruction",
    "context",
    "token",
    "function",
    "completion",
    "response",
    "davinci",
    "claude",
    "gpt",
    "llm",
    "api",
    "openai",
    "anthropic"
  ];
  const keywordPattern = new RegExp(`\\b(${aiKeywords.join("|")})\\b`, "gi");
  sanitized = sanitized.replace(keywordPattern, (match) => `_${match}_`);
  if (escapeQuotes) {
    sanitized = sanitized.replace(/"/g, "\\\"").replace(/'/g, "\\'");
  } else {
    sanitized = sanitized.replace(/["']/g, "");
  }
  if (strictMode) {
    sanitized = sanitized.replace(/[\u0000-\u001F\u007F-\u009F\u2000-\u200F\u2028-\u202F]/g, "");
    sanitized = sanitized.replace(/\.\.\./g, "…");
    sanitized = sanitized.replace(/\-\-\-+/g, "—");
    sanitized = sanitized.replace(/={2,}/g, "==");
    sanitized = sanitized.replace(/(https?:\/\/[^\s]+)/g, "[Link removed]");
  }
  sanitized = sanitized.replace(/(\s*"\w+"\s*:)/g, "【Property】:").replace(/(\[\s*\]|\{\s*\})/g, "【Empty】");
  if (sanitized.length > maxLength) {
    sanitized = sanitized.substring(0, maxLength) + "...";
  }
  return sanitized;
}
function sanitizeData(data, options = {}, maxDepth = 5, currentDepth = 0) {
  if (currentDepth >= maxDepth) {
    return typeof data === "object" && data !== null ? "[Nested object simplified]" : data;
  }
  if (data === null || data === undefined) {
    return data;
  }
  if (typeof data === "string") {
    return sanitizeString(data, options);
  }
  if (typeof data === "number" || typeof data === "boolean") {
    return data;
  }
  if (Array.isArray(data)) {
    return data.map((item) => sanitizeData(item, options, maxDepth, currentDepth + 1));
  }
  if (typeof data === "object") {
    const result = {};
    for (const key in data) {
      if (Object.prototype.hasOwnProperty.call(data, key)) {
        const safeKey = key.replace(/[<>{}\[\]]/g, "");
        result[safeKey] = sanitizeData(data[key], options, maxDepth, currentDepth + 1);
      }
    }
    return result;
  }
  return String(data);
}

