      const hash6 = await walletClient(account).writeContract({
        account,
        address: tokenAddress,
        abi: ERC20_ABI,
        functionName: "approve",
        args: [spender, BigInt(amount)]
      });
      await publicClient.waitForTransactionReceipt({ hash: hash6 });
